<?php
declare(strict_types=1); require_once __DIR__.'/_shared.php'; require_login();
$fields=['name','niche','affiliate_url','short_description','benefits','target_audience','price_range','disclaimer_text','active'];
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $id=(int)($_POST['id']??0); if(($_POST['delete']??'')==='1'&&$id){ db()->prepare('DELETE FROM products WHERE id=?')->execute([$id]); flash('Product deleted.'); redirect('products.php'); } $vals=[]; foreach($fields as $f) $vals[$f]= $f==='active' ? (int)(($_POST[$f]??'0')==='1') : trim((string)($_POST[$f]??'')); if($id){ db()->prepare('UPDATE products SET name=?,niche=?,affiliate_url=?,short_description=?,benefits=?,target_audience=?,price_range=?,disclaimer_text=?,active=?,updated_at=? WHERE id=?')->execute([$vals['name'],$vals['niche'],$vals['affiliate_url'],$vals['short_description'],$vals['benefits'],$vals['target_audience'],$vals['price_range'],$vals['disclaimer_text'],$vals['active'],now_utc(),$id]); flash('Product updated.'); } else { db()->prepare('INSERT INTO products(name,niche,affiliate_url,short_description,benefits,target_audience,price_range,disclaimer_text,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$vals['name'],$vals['niche'],$vals['affiliate_url'],$vals['short_description'],$vals['benefits'],$vals['target_audience'],$vals['price_range'],$vals['disclaimer_text'],$vals['active'],now_utc(),now_utc()]); flash('Product added.'); } redirect('products.php'); }
$edit=null; if(isset($_GET['edit'])){ $st=db()->prepare('SELECT * FROM products WHERE id=?'); $st->execute([(int)$_GET['edit']]); $edit=$st->fetch(); } $rows=db()->query('SELECT * FROM products ORDER BY active DESC, name')->fetchAll(); layout_header('Products'); show_flash(); ?><div class="split"><section class="panel"><h2><?= $edit?'Edit':'Add' ?> product</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><div class="form-grid"><label>Product name<input name="name" required value="<?=h($edit['name']??'') ?>"></label><label>Niche/category<input name="niche" value="<?=h($edit['niche']??'') ?>"></label><label>Affiliate URL<input type="url" name="affiliate_url" required value="<?=h($edit['affiliate_url']??'') ?>"></label><label>Price range<input name="price_range" value="<?=h($edit['price_range']??'') ?>"></label></div><label>Short description<textarea name="short_description"><?=h($edit['short_description']??'') ?></textarea></label><label>Benefits<textarea name="benefits"><?=h($edit['benefits']??'') ?></textarea></label><label>Target audience<textarea name="target_audience"><?=h($edit['target_audience']??'') ?></textarea></label><label>Disclaimer text<textarea name="disclaimer_text"><?=h($edit['disclaimer_text']??'Affiliate disclosure: I may earn a commission from qualifying purchases.') ?></textarea></label><label>Active<select name="active"><option value="1" <?=($edit['active']??1)?'selected':''?>>Active</option><option value="0" <?=isset($edit)&&!$edit['active']?'selected':''?>>Inactive</option></select></label><button>Save product</button></form></section><section class="panel"><h2>Products</h2><div class="table-wrap"><table><tr><th>Name</th><th>Niche</th><th>Active</th><th>Actions</th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['name'])?></td><td><?=h($r['niche'])?></td><td><?= $r['active']?'Yes':'No' ?></td><td><a href="?edit=<?=$r['id']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="delete" value="1"><button class="danger" data-confirm="Delete product and campaigns?">Delete</button></form></td></tr><?php endforeach; ?></table></div></section></div><?php layout_footer();
